<script>
(function(){
  var bal=document.getElementById('dpBal'),apr=document.getElementById('dpApr'),
      pay=document.getElementById('dpPay'),extra=document.getElementById('dpExtra'),
      timeEl=document.getElementById('dpTime'),intEl=document.getElementById('dpInt'),saveEl=document.getElementById('dpSave');
  function money(n){return '$'+Math.round(n).toLocaleString('en-US');}
  function dur(m){var y=Math.floor(m/12),mo=m%12;var s=[];if(y)s.push(y+(y===1?' year':' years'));if(mo)s.push(mo+(mo===1?' month':' months'));return s.join(' ')||'0 months';}
  // returns {months, interest} or null if never pays off
  function sim(balance,monthlyRate,payment){
    var interestPaid=0,months=0;
    while(balance>0.005 && months<1200){
      var i=balance*monthlyRate; interestPaid+=i; balance+=i;
      var p=Math.min(payment,balance);
      if(p<=i){ return null; } // payment cannot cover interest
      balance-=payment; months++;
    }
    return {months:months,interest:interestPaid};
  }
  function calc(){
    var b=parseFloat(bal.value)||0, a=(parseFloat(apr.value)||0)/100/12, p=parseFloat(pay.value)||0, x=parseFloat(extra.value)||0;
    saveEl.style.display='none';
    if(b<=0||p<=0){timeEl.textContent='Enter your numbers';intEl.textContent='';return;}
